def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            color = None
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if grid[y][x] not in (0, 1):
                    color = grid[y][x]
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if color is not None:
                cells = set(comp)
                for y, x in comp:
                    if all((yy,xx) in cells for yy in range(y-1,y+2) for xx in range(x-1,x+2)):
                        out[y][x] = color
    return out
